(()=>{'use strict';const B=ExamBank,C=ExamCore,M=MockCore,root=document.querySelector('#mockExams'),key='science-studio-mocks-v1';let current=null,history=[],saveNotice='',showConfirm=false,reviewKind='all';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),Q=s=>root.querySelector(s);
try{const raw=JSON.parse(localStorage.getItem(key)||'null');current=M.restore(B,raw?.current,C);history=(Array.isArray(raw?.history)?raw.history:[]).map(x=>M.restore(B,x,C)).filter(x=>x&&x.status==='submitted').slice(-6);if(raw?.current&&!current)saveNotice='An older or invalid mock attempt could not be restored. Your practice-bank scores are unchanged.';}catch(e){saveNotice='Saved mocks could not be read. You can start a new attempt; browser storage may be unavailable.';}
function save(){try{localStorage.setItem(key,JSON.stringify({version:1,current,history}));saveNotice=current?.status==='active'?'Answers saved in this browser. The timer continues if you leave or reload.':'Mock results and history saved in this browser.';}catch(e){saveNotice='Browser storage is unavailable or full. Keep this page open; answers may not survive a reload.';}if(Q('#mockSave'))Q('#mockSave').textContent=saveNotice;}
function clock(){if(!current||current.status!=='active')return;if(M.expire(current,Date.now())){save();render();return}const left=M.remaining(current,Date.now());if(Q('#mockTime')){Q('#mockTime').textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');Q('#mockTime').classList.toggle('low',left<=300);}if(Q('#mockWarning')&&left<=300&&!Q('#mockWarning').textContent)Q('#mockWarning').textContent='Five minutes or less remain. Check unanswered and flagged questions.';}
function render(){if(current)M.expire(current,Date.now());root.innerHTML=`<div class="sectionhead"><div><div class="eyebrow">05 / TIMED MOCK EXAMS</div><h2>Put your revision to the test.</h2></div><span class="pill">CORE + EXTENSION</span></div><p>Mixed-topic practice using selected questions from the revision bank. Each paper samples all 11 topics; it is not an official school exam or a prediction of your exam grade.</p><div id="mockBody"></div>`;if(!current)landing();else if(current.status==='active')exam();else results();clock();}
function landing(){Q('#mockBody').innerHTML=`<div class="mockpapers">${['core','extension'].map(kind=>{const p=M.paper(B,kind);return `<article><div class="eyebrow">${p.title} mock</div><h3>${p.questions.length} questions · ${p.marks} marks</h3><p>${p.minutes} minutes at standard time. Eleven automatically marked questions and eleven written responses, one pair from each topic.</p><button class="primary" data-start="${kind}">Start ${p.title} mock</button></article>`}).join('')}</div><div class="mocksetup"><label for="mockExtra">Time allowance <select id="mockExtra"><option value="1">Standard time</option><option value="1.25">25% extra time</option><option value="1.5">50% extra time</option></select></label><p class="small">Choose any required extra time before starting. The countdown starts immediately, continues in the background and submits saved answers at the deadline. If the page is closed, submission is applied when you reopen it. There is no pause. Use only one tab for an attempt.</p><p class="small">Answers and marking guides stay hidden until submission. Use a calculator and paper for working. Written responses are self-assessed afterwards. The durations are practice settings, not official school timings.</p></div><p id="mockSave" class="small" role="status">${esc(saveNotice)}</p><div id="mockHistory"></div>`;root.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{current=M.create(B,b.dataset.start,Date.now(),Number(Q('#mockExtra').value));save();render();});historyView();}
function historyView(){const box=Q('#mockHistory');if(!box)return;box.innerHTML=history.length?`<h3>Previous attempts</h3><p class="small">The six most recent finished attempts are retained in this browser.</p>${history.map((a,i)=>{const r=M.result(B,a,C);return `<button data-history="${i}" class="mockhistory">${M.settings[a.kind].title} · ${new Date(a.startedAt).toLocaleDateString('en-AU')} · ${r.combined===null?'written marking pending':r.combined+'/'+r.total+' including self-assessment'}</button>`}).join('')}`:'';box.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{current=history.splice(Number(b.dataset.history),1)[0];save();render();});}
function finish(reason){if(!current||current.status!=='active')return;M.submit(current,Date.now());showConfirm=false;save();render();Q('#mockResultHeading')?.focus();}
function exam(){const p=M.paper(B,current.kind);Q('#mockBody').innerHTML=`<div class="mockbar"><div><b>${p.title} mock · ${p.marks} marks</b><span id="mockAnswered"></span></div><div class="mockclock" aria-label="Time remaining"><span id="mockTime"></span><small>remaining</small></div><button id="mockSubmit">Submit exam</button></div><p id="mockWarning" role="status" class="small"></p><p id="mockSave" class="small" role="status">${esc(saveNotice||'Answers are saved locally as you work.')}</p><nav id="mockNav" class="mocknav" aria-label="Mock question navigator"></nav><p class="small">✓ answered · ⚑ flagged · outlined = current question. You may move freely between questions before submitting.</p><div id="mockQuestion"></div><div class="mockbottom"><button id="mockPrev">← Previous</button><button id="mockFlag">Flag for review</button><button id="mockNext" class="primary">Next →</button></div><div id="mockConfirm" class="mockconfirm" ${showConfirm?'':'hidden'}></div>`;Q('#mockSubmit').onclick=()=>{showConfirm=true;confirmation(p)};Q('#mockPrev').onclick=()=>navigate(-1);Q('#mockNext').onclick=()=>{if(current.index===p.questions.length-1){showConfirm=true;confirmation(p)}else navigate(1)};Q('#mockFlag').onclick=()=>{if(M.expire(current,Date.now())){save();render();return}const q=p.questions[current.index];current.flags[q.id]=!current.flags[q.id];save();navigation(p)};question(p);if(showConfirm)confirmation(p);}
function navigate(delta){if(M.expire(current,Date.now())){save();render();return}const p=M.paper(B,current.kind);current.index=Math.max(0,Math.min(p.questions.length-1,current.index+delta));save();question(p);Q('#mockQuestionTitle')?.focus();}
function navigation(p){const count=p.questions.filter(q=>M.answered(q,current.answers[q.id],C)).length;Q('#mockAnswered').textContent=`${count}/${p.questions.length} answered · ${current.multiplier===1?'standard time':Math.round((current.multiplier-1)*100)+'% extra time'}`;Q('#mockNav').innerHTML=p.questions.map((q,i)=>`<button data-go="${i}" aria-label="Question ${i+1}: ${esc(q.topicTitle)}, ${M.answered(q,current.answers[q.id],C)?'answered':'unanswered'}${current.flags[q.id]?', flagged':''}" ${i===current.index?'aria-current="step"':''}>${i+1}${M.answered(q,current.answers[q.id],C)?' ✓':''}${current.flags[q.id]?' ⚑':''}</button>`).join('');Q('#mockNav').querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{navigate(Number(b.dataset.go)-current.index)});Q('#mockPrev').disabled=current.index===0;Q('#mockNext').textContent=current.index===p.questions.length-1?'Review & submit':'Next →';Q('#mockFlag').textContent=current.flags[p.questions[current.index].id]?'Remove flag':'Flag for review';Q('#mockFlag').setAttribute('aria-pressed',String(!!current.flags[p.questions[current.index].id]));}
function question(p){const q=p.questions[current.index],value=current.answers[q.id];Q('#mockQuestion').innerHTML=`<article class="examquestion"><div class="examqmeta">Question ${current.index+1} of ${p.questions.length} · ${esc(q.topicTitle)} · ${q.marks} mark${q.marks===1?'':'s'}</div><h3 id="mockQuestionTitle" tabindex="-1">${esc(q.prompt)}</h3>${window.ExamStimuli?.[q.stimulus]||''}${q.type==='written'?`<label for="mockInput">Your response</label><textarea id="mockInput" rows="7" maxlength="6000">${esc(value||'')}</textarea>`:q.type==='number'?`<label class="examnumber" for="mockInput">Answer in ${esc(q.unit)} — number only<input id="mockInput" type="text" inputmode="decimal" maxlength="30" value="${esc(value??'')}"></label>`:`<fieldset><legend class="small">Choose one answer</legend>${q.options.map((s,i)=>`<label class="examoption"><input type="radio" name="mockOption" value="${i}" ${value===i?'checked':''}><span>${String.fromCharCode(65+i)}. ${esc(s)}</span></label>`).join('')}</fieldset>`}<p id="mockInputStatus" class="small" role="status"></p></article>`;const handler=e=>{if(M.expire(current,Date.now())){save();render();return}current.answers[q.id]=q.type==='mc'?Number(e.target.value):e.target.value;save();Q('#mockInputStatus').textContent=q.type==='number'&&e.target.value.trim()&&!C.validAnswer(q,e.target.value)?'Enter a number only (for example 2.5); the unit is shown above.':'';navigation(p)};Q('#mockQuestion').querySelectorAll('input,textarea').forEach(e=>e.oninput=handler);navigation(p);}
function confirmation(p){const missing=p.questions.filter(q=>!M.answered(q,current.answers[q.id],C)).length,flagged=p.questions.filter(q=>current.flags[q.id]).length;Q('#mockConfirm').hidden=false;Q('#mockConfirm').innerHTML=`<h3>Submit this attempt?</h3><p>${missing} unanswered question${missing===1?'':'s'} and ${flagged} flagged. Answers lock after submission. Unanswered questions receive zero; written answers are marked afterwards.</p><button id="mockFinish" class="primary">Finish and view results</button><button id="mockContinue">Keep working</button>`;Q('#mockFinish').onclick=()=>finish('manual');Q('#mockContinue').onclick=()=>{showConfirm=false;Q('#mockConfirm').hidden=true};Q('#mockConfirm').scrollIntoView({block:'nearest'});}
function results(){const p=M.paper(B,current.kind),r=M.result(B,current,C),duration=Math.max(0,Math.round((current.submittedAt-current.startedAt)/60000));Q('#mockBody').innerHTML=`<h3 id="mockResultHeading" tabindex="-1">${p.title} mock results</h3><p>${current.reason==='time'?'Time expired — saved answers were submitted.':'Submitted by you.'} ${duration} minute${duration===1?'':'s'} elapsed. ${r.unanswered} unanswered question${r.unanswered===1?'':'s'}. Your submitted answers are locked.</p><div id="mockResultsSummary"></div><p id="mockSave" class="small" role="status">Results are saved in this browser.</p><div class="mockresulttools"><button id="mockExport">Export this result</button><button id="mockNew">Choose another mock</button></div><h3>Topic breakdown</h3><div id="mockBreakdown"></div><h3>Suggested revision</h3><p class="small">Priorities are based on this small question sample, not a prediction of exam performance. Unmarked written responses need self-assessment before a complete score is available.</p><div id="mockSuggestions"></div><h3>Review answers and mark written responses</h3><label for="mockReviewFilter">Show <select id="mockReviewFilter"><option value="all">All questions</option><option value="written">Written responses</option><option value="mistakes">Incorrect or unanswered auto questions</option></select></label><div id="mockReview" class="mockreview"></div>`;Q('#mockReviewFilter').value=reviewKind;Q('#mockReviewFilter').onchange=e=>{reviewKind=e.target.value;reviews(p)};Q('#mockNew').onclick=()=>{history=history.filter(x=>x.id!==current.id);history.push(current);history=history.slice(-6);current=null;reviewKind='all';showConfirm=false;save();render()};Q('#mockExport').onclick=()=>{const result=M.result(B,current,C),blob=new Blob([JSON.stringify({attempt:current,result},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`science-${current.kind}-mock-result.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};score();reviews(p);}
function score(){const r=M.result(B,current,C);Q('#mockResultsSummary').innerHTML=`<div class="examdashboard"><div><b>${r.auto}/${r.autoTotal}</b><span>automatically marked</span></div><div><b>${r.pending?r.pending+' pending':r.written+'/'+r.writtenTotal}</b><span>written marks (self-assessed; blanks score 0)${r.pending?' · '+r.written+' marks recorded so far':''}</span></div><div><b>${r.combined===null?'Pending':r.combined+'/'+r.total}</b><span>combined practice score${r.combined===null?'':' · includes self-assessment'}</span></div><div><b>${r.combined===null?'—':Math.round(r.combined/r.total*100)+'%'}</b><span>no grade boundary applied</span></div></div>`;Q('#mockBreakdown').innerHTML=`<div class="examtable"><table><thead><tr><th>Topic</th><th>Auto</th><th>Written</th><th>Next step</th></tr></thead><tbody>${r.topics.map(t=>`<tr><th scope="row">${esc(t.title)}</th><td>${t.auto}/${t.autoTotal}</td><td>${t.pending?'Awaiting marking':t.blankWritten?'0/'+t.writtenTotal+' (unanswered)':t.written+'/'+t.writtenTotal+' (self-assessed)'}</td><td>${t.pending?'Mark written response':t.auto<t.autoTotal||t.written<t.writtenTotal?'Revise missed points':'Keep practising'}</td></tr>`).join('')}</tbody></table></div>`;const priority=[...r.topics].sort((a,b)=>(b.autoTotal-b.auto+b.writtenTotal-b.written)-(a.autoTotal-a.auto+a.writtenTotal-a.written));Q('#mockSuggestions').innerHTML=priority.map(t=>`<article class="mocksuggestion"><h4>${esc(t.title)}</h4><p>${t.auto<t.autoTotal?'Revisit the auto question: '+(t.unanswered?'check for blanks and':'review its feedback and')+' explain the correct reasoning. ':''}${t.pending?'Self-assess the written answer to identify the remaining gaps.':t.missing.length?'Written marking points to revise: '+esc(t.missing.join(' ')):'All written marking points were recorded; test them again without the guide.'}</p><button data-revise="${t.id}">Revise ${esc(t.title)} →</button></article>`).join('');Q('#mockSuggestions').querySelectorAll('[data-revise]').forEach(b=>b.onclick=()=>window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:b.dataset.revise})));}
function reviews(p){const list=p.questions.filter(q=>reviewKind==='all'||reviewKind==='written'&&q.type==='written'||reviewKind==='mistakes'&&q.type!=='written'&&!C.grade(q,current.answers[q.id]));Q('#mockReview').innerHTML=list.length?list.map(q=>{const a=current.answers[q.id],answered=M.answered(q,a,C);let html=`<article class="examquestion"><div class="examqmeta">${esc(q.topicTitle)} · ${q.marks} mark${q.marks===1?'':'s'}</div><h4>${esc(q.prompt)}</h4>${window.ExamStimuli?.[q.stimulus]||''}<p><b>Your submitted answer</b></p><p class="mocksubmitted">${esc(answered?(q.type==='mc'?q.options[a]:a):'No valid answer submitted')}</p>`;if(q.type!=='written')return html+`<div class="examfeedback ${C.grade(q,a)?'right':'wrong'}"><b>${C.grade(q,a)?'Correct · 1/1':'0/1'}</b><p>Answer: ${esc(q.type==='mc'?q.options[q.correct]:q.answer+' '+q.unit)}</p><p>${esc(q.explain)}</p></div></article>`;return html+`<details ${!current.assessed[q.id]?'open':''}><summary>Model answer and marking points</summary><p>${esc(q.model)}</p><p class="small">Award one mark for each point demonstrated in your submitted answer. This is self-assessment, not automatic grading.</p>${q.rubric.map((s,i)=>`<label class="examcriterion"><input data-mock-rubric="${q.id}" data-index="${i}" type="checkbox" ${current.rubrics[q.id]?.[i]?'checked':''} ${!answered?'disabled':''}><span>${esc(s)}</span></label>`).join('')}<button data-mark="${q.id}" ${!answered?'disabled':''}>Save written mark</button><p id="mock-mark-${q.id}" class="small" role="status">${!answered?'Unanswered: 0 marks.':current.assessed[q.id]?'Self-assessed: '+q.rubric.filter((_,i)=>current.rubrics[q.id]?.[i]).length+'/'+q.marks:'Awaiting self-assessment.'}</p></details></article>`;}).join(''):'<p>No questions in this review category.</p>';Q('#mockReview').querySelectorAll('[data-mock-rubric]').forEach(e=>e.onchange=()=>{const id=e.dataset.mockRubric;current.rubrics[id]??=[];current.rubrics[id][Number(e.dataset.index)]=e.checked;current.assessed[id]=false;save();Q('#mock-mark-'+id).textContent='Marking points changed. Save the written mark to update the score.';score()});Q('#mockReview').querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{const id=b.dataset.mark,q=p.questions.find(q=>q.id===id);if(!M.answered(q,current.answers[id],C))return;current.assessed[id]=true;save();Q('#mock-mark-'+id).textContent='Self-assessed: '+q.rubric.filter((_,i)=>current.rubrics[id]?.[i]).length+'/'+q.marks;score()});}
// Absolute deadlines avoid timer drift while background tabs throttle callbacks.
setInterval(clock,1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)clock()});window.addEventListener('pageshow',clock);if(current&&M.expire(current,Date.now()))save();render();
})();
